template <class PROCESS>
void GeneratedSingleChildTransform::InitializeStatementTrampoline(PEGTransformer &transformer,
                                                                  ParseResult &parse_result, PROCESS &process) {
	auto &list_pr = parse_result.Cast<ListParseResult>();
	auto &choice_pr = list_pr.Child<ChoiceParseResult>(0);
	auto &choice_result = choice_pr.GetResult();
	process.ReserveChildSlots(1);
	auto child_rule = choice_result.GetRule();
	if (!child_rule) {
		throw InternalException("No transform process registered for rule '%s'", choice_result.Name());
	}
	process.PushChild({*child_rule, choice_result}, 0);
}

template <class PROCESS>
arena_ptr<TransformResultValue> GeneratedSingleChildTransform::FinalizeStatementTrampoline(PEGTransformer &transformer,
                                                                                           ParseResult &parse_result,
                                                                                           PROCESS &process) {
	auto result = process.template TakeResult<unique_ptr<SQLStatement>>(0);
	if (!transformer.named_parameter_map.empty()) {
		result->named_param_map = transformer.named_parameter_map;
	}
	result->has_anonymous_parameters = transformer.has_anonymous_parameters;
	return transformer.MakeResult<unique_ptr<SQLStatement>>(std::move(result));
}

template <class PROCESS>
void GeneratedSingleChildTransform::InitializeIdentifierOrKeywordTrampoline(PEGTransformer &transformer,
                                                                            ParseResult &parse_result,
                                                                            PROCESS &process) {
	process.ReserveChildSlots(0);
}

template <class PROCESS>
arena_ptr<TransformResultValue>
GeneratedSingleChildTransform::FinalizeIdentifierOrKeywordTrampoline(PEGTransformer &transformer,
                                                                     ParseResult &parse_result, PROCESS &process) {
	auto result = PEGTransformerFactory::TransformIdentifierOrKeyword(transformer, parse_result);
	return transformer.MakeResult<string>(std::move(result));
}

template <class PROCESS>
void GeneratedSingleChildTransform::InitializeAlterStatementTrampoline(PEGTransformer &transformer,
                                                                       ParseResult &parse_result, PROCESS &process) {
	auto &list_pr = parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(1);
	process.PushChild({transformer.GetRule(PEGRuleId::AlterOptions), list_pr.GetChild(1)}, 0);
}

template <class PROCESS>
arena_ptr<TransformResultValue>
GeneratedSingleChildTransform::FinalizeAlterStatementTrampoline(PEGTransformer &transformer, ParseResult &parse_result,
                                                                PROCESS &process) {
	auto alter_options = process.template TakeResult<unique_ptr<AlterInfo>>(0);
	auto result = PEGTransformerFactory::TransformAlterStatement(transformer, std::move(alter_options));
	return transformer.MakeResult<unique_ptr<SQLStatement>>(std::move(result));
}

template <class PROCESS>
void GeneratedSingleChildTransform::InitializeAlterOptionsTrampoline(PEGTransformer &transformer,
                                                                     ParseResult &parse_result, PROCESS &process) {
	auto &list_pr = parse_result.Cast<ListParseResult>();
	auto &choice_pr = list_pr.Child<ChoiceParseResult>(0);
	auto &choice_result = choice_pr.GetResult();
	process.ReserveChildSlots(1);
	auto child_rule = choice_result.GetRule();
	auto has_transform_process = child_rule && child_rule->transform_process;
	if (!has_transform_process) {
		throw InternalException("No transform process registered for rule '%s'", choice_result.Name());
	}
	process.PushChild({*child_rule, choice_result}, 0);
}

template <class PROCESS>
arena_ptr<TransformResultValue>
GeneratedSingleChildTransform::FinalizeAlterOptionsTrampoline(PEGTransformer &transformer, ParseResult &parse_result,
                                                              PROCESS &process) {
	auto result = process.template TakeResult<unique_ptr<AlterInfo>>(0);
	return transformer.MakeResult<unique_ptr<AlterInfo>>(std::move(result));
}

void PEGTransformerFactory::InitializeAlterTableStmtTrampoline(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(list_pr.GetChild(3));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(3 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::AlterTableOptions), list_items[child_idx].get()},
		                  2 + child_idx);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::BaseTableName), list_pr.GetChild(2)}, 1);
	auto &if_exists_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (if_exists_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::IfExists), if_exists_opt.GetResult()}, 0);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeAlterTableStmtTrampoline(PEGTransformer &transformer,
                                                        GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_child_count = CountParseResultsFromList(list_pr.GetChild(3));
	optional<bool> if_exists {};
	if (process.child_results[0]) {
		if_exists = process.TakeResult<bool>(0);
	}
	auto base_table_name = process.TakeResult<unique_ptr<BaseTableRef>>(1);
	vector<unique_ptr<AlterTableInfo>> alter_table_options;
	alter_table_options.reserve(dynamic_child_count);
	for (idx_t i = 2; i < 2 + dynamic_child_count; i++) {
		alter_table_options.push_back(process.TakeResult<unique_ptr<AlterTableInfo>>(i));
	}
	auto result = PEGTransformerFactory::TransformAlterTableStmt(transformer, if_exists, std::move(base_table_name),
	                                                             std::move(alter_table_options));
	return transformer.MakeResult<unique_ptr<AlterInfo>>(std::move(result));
}

void PEGTransformerFactory::InitializeAlterSchemaStmtTrampoline(PEGTransformer &transformer,
                                                                GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(3);
	process.PushChild({transformer.GetRule(PEGRuleId::AlterSchemaOptions), list_pr.GetChild(3)}, 2);
	process.PushChild({transformer.GetRule(PEGRuleId::QualifiedName), list_pr.GetChild(2)}, 1);
	auto &if_exists_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (if_exists_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::IfExists), if_exists_opt.GetResult()}, 0);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeAlterSchemaStmtTrampoline(PEGTransformer &transformer,
                                                         GeneratedTransformProcess &process) {
	optional<bool> if_exists {};
	if (process.child_results[0]) {
		if_exists = process.TakeResult<bool>(0);
	}
	auto qualified_name = process.TakeResult<QualifiedName>(1);
	auto alter_schema_options = process.TakeResult<unique_ptr<AlterTableInfo>>(2);
	auto result = PEGTransformerFactory::TransformAlterSchemaStmt(transformer, if_exists, qualified_name,
	                                                              std::move(alter_schema_options));
	return transformer.MakeResult<unique_ptr<AlterInfo>>(std::move(result));
}

template <class PROCESS>
void GeneratedSingleChildTransform::InitializeAlterSchemaOptionsTrampoline(PEGTransformer &transformer,
                                                                           ParseResult &parse_result,
                                                                           PROCESS &process) {
	auto &list_pr = parse_result.Cast<ListParseResult>();
	auto &choice_pr = list_pr.Child<ChoiceParseResult>(0);
	auto &choice_result = choice_pr.GetResult();
	process.ReserveChildSlots(1);
	auto child_rule = choice_result.GetRule();
	auto has_transform_process = child_rule && child_rule->transform_process;
	if (!has_transform_process) {
		throw InternalException("No transform process registered for rule '%s'", choice_result.Name());
	}
	process.PushChild({*child_rule, choice_result}, 0);
}

