void PEGTransformerFactory::InitializeSpecializedOptionListTrampoline(PEGTransformer &transformer,
                                                                      GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (repeat_opt.HasResult()) {
		auto &repeat_pr = repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto repeat_children = repeat_pr.GetChildren();
		dynamic_child_count = repeat_children.size();
		process.ReserveChildSlots(2 + dynamic_child_count - 1);
		for (idx_t i = repeat_children.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule(PEGRuleId::SpecializedOptionTail), repeat_children[child_idx].get()},
			                  1 + child_idx);
		}
	} else {
		process.ReserveChildSlots(2 - 1);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::SpecializedOption), list_pr.GetChild(0)}, 0);
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeSpecializedOptionListTrampoline(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (dynamic_repeat_opt.HasResult()) {
		auto &dynamic_repeat_pr = dynamic_repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
		dynamic_child_count = dynamic_repeat_children.size();
	}
	auto specialized_option = process.TakeResult<GenericCopyOption>(0);
	optional<vector<GenericCopyOption>> specialized_option_tail {};
	if (dynamic_child_count > 0) {
		vector<GenericCopyOption> specialized_option_tail_value;
		specialized_option_tail_value.reserve(dynamic_child_count);
		for (idx_t i = 1; i < 1 + dynamic_child_count; i++) {
			specialized_option_tail_value.push_back(process.TakeResult<GenericCopyOption>(i));
		}
		specialized_option_tail = std::move(specialized_option_tail_value);
	}
	auto result =
	    PEGTransformerFactory::TransformSpecializedOptionList(transformer, specialized_option, specialized_option_tail);
	return transformer.MakeResult<vector<GenericCopyOption>>(std::move(result));
}

