void PEGTransformerFactory::InitializeRelOptionListTrampoline(PEGTransformer &transformer,
                                                              GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(
	    PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(0)));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::RelOption), list_items[child_idx].get()}, 0 + child_idx);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeRelOptionListTrampoline(PEGTransformer &transformer,
                                                       GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_child_count =
	    CountParseResultsFromList(PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(0)));
	vector<pair<Identifier, unique_ptr<ParsedExpression>>> rel_option;
	rel_option.reserve(dynamic_child_count);
	for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
		rel_option.push_back(process.TakeResult<pair<Identifier, unique_ptr<ParsedExpression>>>(i));
	}
	auto result = PEGTransformerFactory::TransformRelOptionList(transformer, std::move(rel_option));
	return transformer.MakeResult<case_insensitive_map_t<unique_ptr<ParsedExpression>>>(std::move(result));
}

