template <class PROCESS>
void GeneratedSingleChildTransform::InitializeRelOptionNameTrampoline(PEGTransformer &transformer,
                                                                      ParseResult &parse_result, PROCESS &process) {
	auto &list_pr = parse_result.Cast<ListParseResult>();
	auto &choice_pr = list_pr.Child<ChoiceParseResult>(0);
	auto &choice_result = choice_pr.GetResult();
	process.ReserveChildSlots(1);
	auto child_rule = choice_result.GetRule();
	auto has_transform_process = child_rule && child_rule->transform_process;
	if (choice_result.Name().empty() || choice_result.type == ParseResultType::IDENTIFIER ||
	    choice_result.type == ParseResultType::KEYWORD || choice_result.type == ParseResultType::STRING) {
		return;
	}
	if (!has_transform_process &&
	    (choice_result.Name() == "DottedColLabel" || choice_result.Name() == "StringLiteral")) {
		return;
	}
	if (!has_transform_process &&
	    (choice_result.type == ParseResultType::IDENTIFIER || choice_result.type == ParseResultType::KEYWORD ||
	     choice_result.type == ParseResultType::STRING || choice_result.type == ParseResultType::OPERATOR ||
	     choice_result.type == ParseResultType::CHOICE || choice_result.type == ParseResultType::LIST)) {
		return;
	}
	if (!has_transform_process) {
		throw InternalException("No transform process registered for rule '%s'", choice_result.Name());
	}
	process.PushChild({*child_rule, choice_result}, 0);
}

template <class PROCESS>
arena_ptr<TransformResultValue>
GeneratedSingleChildTransform::FinalizeRelOptionNameTrampoline(PEGTransformer &transformer, ParseResult &parse_result,
                                                               PROCESS &process) {
	string child;
	if (process.child_results[0]) {
		child = process.template TakeResult<string>(0);
	} else {
		auto &list_pr = parse_result.Cast<ListParseResult>();
		auto &choice_result = list_pr.Child<ChoiceParseResult>(0).GetResult();
		if (choice_result.type == ParseResultType::IDENTIFIER) {
			child = choice_result.Cast<IdentifierParseResult>().identifier.GetIdentifierName();
		} else if (choice_result.type == ParseResultType::KEYWORD) {
			child = choice_result.Cast<KeywordParseResult>().keyword;
		} else if (choice_result.type == ParseResultType::STRING) {
			child = choice_result.Cast<StringLiteralParseResult>().result;
		} else if (choice_result.type == ParseResultType::OPERATOR) {
			child = choice_result.Cast<OperatorParseResult>().operator_token;
		} else {
			child = PEGTransformerFactory::TransformIdentifierOrKeyword(transformer, choice_result);
		}
	}
	auto result = PEGTransformerFactory::TransformRelOptionName(transformer, child);
	return transformer.MakeResult<Identifier>(std::move(result));
}

void PEGTransformerFactory::InitializeDottedColLabelTrampoline(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (repeat_opt.HasResult()) {
		auto &repeat_pr = repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto repeat_children = repeat_pr.GetChildren();
		dynamic_child_count = repeat_children.size();
		process.ReserveChildSlots(2 + dynamic_child_count - 1);
		for (idx_t i = repeat_children.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule(PEGRuleId::DotColLabel), repeat_children[child_idx].get()},
			                  1 + child_idx);
		}
	} else {
		process.ReserveChildSlots(2 - 1);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::ColLabel), list_pr.GetChild(0)}, 0);
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeDottedColLabelTrampoline(PEGTransformer &transformer,
                                                        GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (dynamic_repeat_opt.HasResult()) {
		auto &dynamic_repeat_pr = dynamic_repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
		dynamic_child_count = dynamic_repeat_children.size();
	}
	auto col_label = process.TakeResult<string>(0);
	optional<vector<string>> dot_col_label {};
	if (dynamic_child_count > 0) {
		vector<string> dot_col_label_value;
		dot_col_label_value.reserve(dynamic_child_count);
		for (idx_t i = 1; i < 1 + dynamic_child_count; i++) {
			dot_col_label_value.push_back(process.TakeResult<string>(i));
		}
		dot_col_label = std::move(dot_col_label_value);
	}
	auto result = PEGTransformerFactory::TransformDottedColLabel(transformer, col_label, dot_col_label);
	return transformer.MakeResult<string>(std::move(result));
}

