void PEGTransformerFactory::InitializeMacroParametersTrampoline(PEGTransformer &transformer,
                                                                GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(list_pr.GetChild(0));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::MacroParameter), list_items[child_idx].get()}, 0 + child_idx);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeMacroParametersTrampoline(PEGTransformer &transformer,
                                                         GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_child_count = CountParseResultsFromList(list_pr.GetChild(0));
	vector<MacroParameter> macro_parameter;
	macro_parameter.reserve(dynamic_child_count);
	for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
		macro_parameter.push_back(process.TakeResult<MacroParameter>(i));
	}
	auto result = PEGTransformerFactory::TransformMacroParameters(transformer, std::move(macro_parameter));
	return transformer.MakeResult<vector<MacroParameter>>(std::move(result));
}

