void PEGTransformerFactory::InitializeColumnIdListTrampoline(PEGTransformer &transformer,
                                                             GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(
	    PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(0)));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::ColId), list_items[child_idx].get()}, 0 + child_idx);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeColumnIdListTrampoline(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_child_count =
	    CountParseResultsFromList(PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(0)));
	vector<Identifier> col_id;
	col_id.reserve(dynamic_child_count);
	for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
		col_id.push_back(process.TakeResult<Identifier>(i));
	}
	auto result = PEGTransformerFactory::TransformColumnIdList(transformer, col_id);
	return transformer.MakeResult<vector<string>>(std::move(result));
}

void PEGTransformerFactory::InitializeDottedIdentifierTrampoline(PEGTransformer &transformer,
                                                                 GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (repeat_opt.HasResult()) {
		auto &repeat_pr = repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto repeat_children = repeat_pr.GetChildren();
		dynamic_child_count = repeat_children.size();
		process.ReserveChildSlots(1 + dynamic_child_count - 1);
		for (idx_t i = repeat_children.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule(PEGRuleId::DotColLabel), repeat_children[child_idx].get()},
			                  0 + child_idx);
		}
	} else {
		process.ReserveChildSlots(1 - 1);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeDottedIdentifierTrampoline(PEGTransformer &transformer,
                                                          GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (dynamic_repeat_opt.HasResult()) {
		auto &dynamic_repeat_pr = dynamic_repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
		dynamic_child_count = dynamic_repeat_children.size();
	}
	auto identifier = list_pr.GetChild(0).Cast<IdentifierParseResult>().identifier;
	optional<vector<string>> dot_col_label {};
	if (dynamic_child_count > 0) {
		vector<string> dot_col_label_value;
		dot_col_label_value.reserve(dynamic_child_count);
		for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
			dot_col_label_value.push_back(process.TakeResult<string>(i));
		}
		dot_col_label = std::move(dot_col_label_value);
	}
	auto result = PEGTransformerFactory::TransformDottedIdentifier(transformer, identifier, dot_col_label);
	return transformer.MakeResult<vector<string>>(std::move(result));
}

