void PEGTransformerFactory::InitializeEnumStringLiteralListTrampoline(PEGTransformer &transformer,
                                                                      GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_opt = list_pr.GetChild(2).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (repeat_opt.HasResult()) {
		auto &repeat_pr = repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto repeat_children = repeat_pr.GetChildren();
		dynamic_child_count = repeat_children.size();
		process.ReserveChildSlots(1 + dynamic_child_count - 1);
		for (idx_t i = repeat_children.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule(PEGRuleId::ArrayBounds), repeat_children[child_idx].get()},
			                  0 + child_idx);
		}
	} else {
		process.ReserveChildSlots(1 - 1);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeEnumStringLiteralListTrampoline(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_repeat_opt = list_pr.GetChild(2).Cast<OptionalParseResult>();
	if (dynamic_repeat_opt.HasResult()) {
		auto &dynamic_repeat_pr = dynamic_repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
		dynamic_child_count = dynamic_repeat_children.size();
	}
	optional<vector<string>> string_literal {};
	auto &string_literal_opt =
	    PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(1)).Cast<OptionalParseResult>();
	if (string_literal_opt.HasResult()) {
		vector<string> string_literal_value;
		auto string_literal_items = PEGTransformerFactory::ExtractParseResultsFromList(string_literal_opt.GetResult());
		string_literal_value.reserve(string_literal_items.size());
		for (auto &string_literal_item : string_literal_items) {
			auto string_literal_item_value =
			    PEGTransformerFactory::TransformStringLiteral(transformer, string_literal_item.get());
			string_literal_value.push_back(string_literal_item_value);
		}
		string_literal = std::move(string_literal_value);
	}
	optional<vector<int64_t>> array_bounds {};
	if (dynamic_child_count > 0) {
		vector<int64_t> array_bounds_value;
		array_bounds_value.reserve(dynamic_child_count);
		for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
			array_bounds_value.push_back(process.TakeResult<int64_t>(i));
		}
		array_bounds = std::move(array_bounds_value);
	}
	auto result = PEGTransformerFactory::TransformEnumStringLiteralList(transformer, string_literal, array_bounds);
	return transformer.MakeResult<unique_ptr<CreateTypeInfo>>(std::move(result));
}

void PEGTransformerFactory::InitializeCreateViewStmtTrampoline(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(7);
	process.PushChild({transformer.GetRule(PEGRuleId::SelectStatementInternal), list_pr.GetChild(8)}, 6);
	auto &with_list_opt = list_pr.GetChild(6).Cast<OptionalParseResult>();
	if (with_list_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::WithList), with_list_opt.GetResult()}, 5);
	}
	auto &insert_column_list_opt = list_pr.GetChild(5).Cast<OptionalParseResult>();
	if (insert_column_list_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::InsertColumnList), insert_column_list_opt.GetResult()}, 4);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::QualifiedName), list_pr.GetChild(4)}, 3);
	auto &if_not_exists_opt = list_pr.GetChild(3).Cast<OptionalParseResult>();
	if (if_not_exists_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::IfNotExists), if_not_exists_opt.GetResult()}, 2);
	}
	auto &create_recursive_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (create_recursive_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::CreateRecursive), create_recursive_opt.GetResult()}, 1);
	}
	auto &create_secure_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (create_secure_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::CreateSecure), create_secure_opt.GetResult()}, 0);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeCreateViewStmtTrampoline(PEGTransformer &transformer,
                                                        GeneratedTransformProcess &process) {
	optional<bool> create_secure {};
	if (process.child_results[0]) {
		create_secure = process.TakeResult<bool>(0);
	}
	optional<bool> create_recursive {};
	if (process.child_results[1]) {
		create_recursive = process.TakeResult<bool>(1);
	}
	optional<bool> if_not_exists {};
	if (process.child_results[2]) {
		if_not_exists = process.TakeResult<bool>(2);
	}
	auto qualified_name = process.TakeResult<QualifiedName>(3);
	optional<vector<string>> insert_column_list {};
	if (process.child_results[4]) {
		insert_column_list = process.TakeResult<vector<string>>(4);
	}
	optional<case_insensitive_map_t<unique_ptr<ParsedExpression>>> with_list {};
	if (process.child_results[5]) {
		with_list = process.TakeResult<case_insensitive_map_t<unique_ptr<ParsedExpression>>>(5);
	}
	auto select_statement_internal = process.TakeResult<unique_ptr<SelectStatement>>(6);
	auto result = PEGTransformerFactory::TransformCreateViewStmt(
	    transformer, create_secure, create_recursive, if_not_exists, qualified_name, insert_column_list,
	    std::move(with_list), std::move(select_statement_internal));
	return transformer.MakeResult<unique_ptr<CreateStatement>>(std::move(result));
}

