void PEGTransformerFactory::InitializeFunctionExpressionTrampoline(PEGTransformer &transformer,
                                                                   GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(5);
	auto &over_clause_opt = list_pr.GetChild(5).Cast<OptionalParseResult>();
	if (over_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::OverClause), over_clause_opt.GetResult()}, 4);
	}
	auto &filter_clause_opt = list_pr.GetChild(3).Cast<OptionalParseResult>();
	if (filter_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::FilterClause), filter_clause_opt.GetResult()}, 3);
	}
	auto &within_group_clause_opt = list_pr.GetChild(2).Cast<OptionalParseResult>();
	if (within_group_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::WithinGroupClause), within_group_clause_opt.GetResult()}, 2);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::FunctionExpressionArguments), list_pr.GetChild(1)}, 1);
	process.PushChild({transformer.GetRule(PEGRuleId::FunctionIdentifier), list_pr.GetChild(0)}, 0);
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeFunctionExpressionTrampoline(PEGTransformer &transformer,
                                                            GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto function_identifier = process.TakeResult<QualifiedName>(0);
	auto function_expression_arguments = process.TakeResult<MethodArguments>(1);
	optional<vector<OrderByNode>> within_group_clause {};
	if (process.child_results[2]) {
		within_group_clause = process.TakeResult<vector<OrderByNode>>(2);
	}
	optional<unique_ptr<ParsedExpression>> filter_clause {};
	if (process.child_results[3]) {
		filter_clause = process.TakeResult<unique_ptr<ParsedExpression>>(3);
	}
	bool has_result {};
	auto &has_result_opt = list_pr.GetChild(4).Cast<OptionalParseResult>();
	has_result = has_result_opt.HasResult();
	optional<unique_ptr<WindowExpression>> over_clause {};
	if (process.child_results[4]) {
		over_clause = process.TakeResult<unique_ptr<WindowExpression>>(4);
	}
	auto result = PEGTransformerFactory::TransformFunctionExpression(
	    transformer, function_identifier, std::move(function_expression_arguments), std::move(within_group_clause),
	    std::move(filter_clause), has_result, std::move(over_clause));
	return transformer.MakeResult<unique_ptr<ParsedExpression>>(std::move(result));
}

