void PEGTransformerFactory::InitializeFunctionExpressionArgumentListTrampoline(PEGTransformer &transformer,
                                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(4);
	auto &ignore_or_respect_nulls_opt = list_pr.GetChild(3).Cast<OptionalParseResult>();
	if (ignore_or_respect_nulls_opt.HasResult()) {
		process.PushChild(
		    {transformer.GetRule(PEGRuleId::IgnoreOrRespectNulls), ignore_or_respect_nulls_opt.GetResult()}, 3);
	}
	auto &order_by_clause_opt = list_pr.GetChild(2).Cast<OptionalParseResult>();
	if (order_by_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::OrderByClause), order_by_clause_opt.GetResult()}, 2);
	}
	auto &function_argument_list_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (function_argument_list_opt.HasResult()) {
		process.PushChild(
		    {transformer.GetRule(PEGRuleId::FunctionArgumentList), function_argument_list_opt.GetResult()}, 1);
	}
	auto &distinct_or_all_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (distinct_or_all_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::DistinctOrAll), distinct_or_all_opt.GetResult()}, 0);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeFunctionExpressionArgumentListTrampoline(PEGTransformer &transformer,
                                                                        GeneratedTransformProcess &process) {
	optional<bool> distinct_or_all {};
	if (process.child_results[0]) {
		distinct_or_all = process.TakeResult<bool>(0);
	}
	optional<vector<FunctionArgument>> function_argument_list {};
	if (process.child_results[1]) {
		function_argument_list = process.TakeResult<vector<FunctionArgument>>(1);
	}
	optional<vector<OrderByNode>> order_by_clause {};
	if (process.child_results[2]) {
		order_by_clause = process.TakeResult<vector<OrderByNode>>(2);
	}
	optional<bool> ignore_or_respect_nulls {};
	if (process.child_results[3]) {
		ignore_or_respect_nulls = process.TakeResult<bool>(3);
	}
	auto result = PEGTransformerFactory::TransformFunctionExpressionArgumentList(
	    transformer, distinct_or_all, std::move(function_argument_list), std::move(order_by_clause),
	    ignore_or_respect_nulls);
	return transformer.MakeResult<MethodArguments>(std::move(result));
}

void PEGTransformerFactory::InitializeFunctionArgumentListTrampoline(PEGTransformer &transformer,
                                                                     GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(list_pr.GetChild(0));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::FunctionArgument), list_items[child_idx].get()},
		                  0 + child_idx);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeFunctionArgumentListTrampoline(PEGTransformer &transformer,
                                                              GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_child_count = CountParseResultsFromList(list_pr.GetChild(0));
	vector<FunctionArgument> function_argument;
	function_argument.reserve(dynamic_child_count);
	for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
		function_argument.push_back(process.TakeResult<FunctionArgument>(i));
	}
	auto result = PEGTransformerFactory::TransformFunctionArgumentList(transformer, std::move(function_argument));
	return transformer.MakeResult<vector<FunctionArgument>>(std::move(result));
}

template <class PROCESS>
void GeneratedSingleChildTransform::InitializeFunctionIdentifierTrampoline(PEGTransformer &transformer,
                                                                           ParseResult &parse_result,
                                                                           PROCESS &process) {
	auto &list_pr = parse_result.Cast<ListParseResult>();
	auto &choice_pr = list_pr.Child<ChoiceParseResult>(0);
	auto &choice_result = choice_pr.GetResult();
	process.ReserveChildSlots(1);
	auto child_rule = choice_result.GetRule();
	auto has_transform_process = child_rule && child_rule->transform_process;
	if (!has_transform_process) {
		throw InternalException("No transform process registered for rule '%s'", choice_result.Name());
	}
	process.PushChild({*child_rule, choice_result}, 0);
}

