void PEGTransformerFactory::InitializeWindowFrameContentsTrampoline(PEGTransformer &transformer,
                                                                    GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(3);
	auto &frame_clause_opt = list_pr.GetChild(2).Cast<OptionalParseResult>();
	if (frame_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::FrameClause), frame_clause_opt.GetResult()}, 2);
	}
	auto &order_by_clause_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (order_by_clause_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::OrderByClause), order_by_clause_opt.GetResult()}, 1);
	}
	auto &window_partition_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (window_partition_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::WindowPartition), window_partition_opt.GetResult()}, 0);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeWindowFrameContentsTrampoline(PEGTransformer &transformer,
                                                             GeneratedTransformProcess &process) {
	optional<vector<unique_ptr<ParsedExpression>>> window_partition {};
	if (process.child_results[0]) {
		window_partition = process.TakeResult<vector<unique_ptr<ParsedExpression>>>(0);
	}
	optional<vector<OrderByNode>> order_by_clause {};
	if (process.child_results[1]) {
		order_by_clause = process.TakeResult<vector<OrderByNode>>(1);
	}
	optional<WindowFrame> frame_clause {};
	if (process.child_results[2]) {
		frame_clause = process.TakeResult<WindowFrame>(2);
	}
	auto result = PEGTransformerFactory::TransformWindowFrameContents(
	    transformer, std::move(window_partition), std::move(order_by_clause), std::move(frame_clause));
	return transformer.MakeResult<unique_ptr<WindowExpression>>(std::move(result));
}

