void PEGTransformerFactory::InitializeRowExpressionTrampoline(PEGTransformer &transformer,
                                                              GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &list_opt = PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(1)).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (list_opt.HasResult()) {
		auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(list_opt.GetResult());
		dynamic_child_count = list_items.size();
		process.ReserveChildSlots(1 + dynamic_child_count - 1);
		for (idx_t i = list_items.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule(PEGRuleId::Expression), list_items[child_idx].get()}, 0 + child_idx);
		}
	} else {
		process.ReserveChildSlots(1 - 1);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeRowExpressionTrampoline(PEGTransformer &transformer,
                                                       GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_list_opt =
	    PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(1)).Cast<OptionalParseResult>();
	if (dynamic_list_opt.HasResult()) {
		dynamic_child_count = CountParseResultsFromList(dynamic_list_opt.GetResult());
	}
	optional<vector<unique_ptr<ParsedExpression>>> expression {};
	auto &expression_opt =
	    PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(1)).Cast<OptionalParseResult>();
	if (expression_opt.HasResult()) {
		vector<unique_ptr<ParsedExpression>> expression_value;
		expression_value.reserve(dynamic_child_count);
		for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
			expression_value.push_back(process.TakeResult<unique_ptr<ParsedExpression>>(i));
		}
		expression = std::move(expression_value);
	}
	auto result = PEGTransformerFactory::TransformRowExpression(transformer, std::move(expression));
	return transformer.MakeResult<unique_ptr<ParsedExpression>>(std::move(result));
}

