void PEGTransformerFactory::InitializeOverlayParametersTrampoline(PEGTransformer &transformer,
                                                                  GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(4);
	auto &for_expression_opt = list_pr.GetChild(4).Cast<OptionalParseResult>();
	if (for_expression_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::ForExpression), for_expression_opt.GetResult()}, 3);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::FromExpression), list_pr.GetChild(3)}, 2);
	process.PushChild({transformer.GetRule(PEGRuleId::Expression), list_pr.GetChild(2)}, 1);
	process.PushChild({transformer.GetRule(PEGRuleId::Expression), list_pr.GetChild(0)}, 0);
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeOverlayParametersTrampoline(PEGTransformer &transformer,
                                                           GeneratedTransformProcess &process) {
	auto expression = process.TakeResult<unique_ptr<ParsedExpression>>(0);
	auto expression_1 = process.TakeResult<unique_ptr<ParsedExpression>>(1);
	auto from_expression = process.TakeResult<unique_ptr<ParsedExpression>>(2);
	optional<unique_ptr<ParsedExpression>> for_expression {};
	if (process.child_results[3]) {
		for_expression = process.TakeResult<unique_ptr<ParsedExpression>>(3);
	}
	auto result =
	    PEGTransformerFactory::TransformOverlayParameters(transformer, std::move(expression), std::move(expression_1),
	                                                      std::move(from_expression), std::move(for_expression));
	return transformer.MakeResult<vector<unique_ptr<ParsedExpression>>>(std::move(result));
}

