void PEGTransformerFactory::InitializeColumnListTrampoline(PEGTransformer &transformer,
                                                           GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(list_pr.GetChild(0));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::ColId), list_items[child_idx].get()}, 0 + child_idx);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeColumnListTrampoline(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_child_count = CountParseResultsFromList(list_pr.GetChild(0));
	vector<Identifier> col_id;
	col_id.reserve(dynamic_child_count);
	for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
		col_id.push_back(process.TakeResult<Identifier>(i));
	}
	auto result = PEGTransformerFactory::TransformColumnList(transformer, col_id);
	return transformer.MakeResult<vector<string>>(std::move(result));
}

