template <class PROCESS>
arena_ptr<TransformResultValue> GeneratedSingleChildTransform::FinalizeUpdateExtensionsStatementTrampoline(
    PEGTransformer &transformer, ParseResult &parse_result, PROCESS &process) {
	auto &list_pr = parse_result.Cast<ListParseResult>();
	optional<vector<Identifier>> identifier {};
	auto &identifier_opt = list_pr.GetChild(2).Cast<OptionalParseResult>();
	if (identifier_opt.HasResult()) {
		vector<Identifier> identifier_value;
		auto identifier_items = PEGTransformerFactory::ExtractParseResultsFromList(
		    PEGTransformerFactory::ExtractResultFromParens(identifier_opt.GetResult()));
		identifier_value.reserve(identifier_items.size());
		for (auto &identifier_item : identifier_items) {
			auto identifier_item_value = identifier_item.get().Cast<IdentifierParseResult>().identifier;
			identifier_value.push_back(identifier_item_value);
		}
		identifier = std::move(identifier_value);
	}
	auto result = PEGTransformerFactory::TransformUpdateExtensionsStatement(transformer, identifier);
	return transformer.MakeResult<unique_ptr<SQLStatement>>(std::move(result));
}

