void PEGTransformerFactory::InitializeInsertValuesListTrampoline(PEGTransformer &transformer,
                                                                 GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(
	    PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(2)));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(2 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::Expression), list_items[child_idx].get()}, 1 + child_idx);
	}
	auto &insert_column_list_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (insert_column_list_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::InsertColumnList), insert_column_list_opt.GetResult()}, 0);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeInsertValuesListTrampoline(PEGTransformer &transformer,
                                                          GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_child_count =
	    CountParseResultsFromList(PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(2)));
	optional<vector<string>> insert_column_list {};
	if (process.child_results[0]) {
		insert_column_list = process.TakeResult<vector<string>>(0);
	}
	vector<unique_ptr<ParsedExpression>> expression;
	expression.reserve(dynamic_child_count);
	for (idx_t i = 1; i < 1 + dynamic_child_count; i++) {
		expression.push_back(process.TakeResult<unique_ptr<ParsedExpression>>(i));
	}
	auto result =
	    PEGTransformerFactory::TransformInsertValuesList(transformer, insert_column_list, std::move(expression));
	return transformer.MakeResult<unique_ptr<MergeIntoAction>>(std::move(result));
}

