void PEGTransformerFactory::InitializeSelectSetOpChainTrampoline(PEGTransformer &transformer,
                                                                 GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (repeat_opt.HasResult()) {
		auto &repeat_pr = repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto repeat_children = repeat_pr.GetChildren();
		dynamic_child_count = repeat_children.size();
		process.ReserveChildSlots(2 + dynamic_child_count - 1);
		for (idx_t i = repeat_children.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule(PEGRuleId::SelectSetOpChainTail), repeat_children[child_idx].get()},
			                  1 + child_idx);
		}
	} else {
		process.ReserveChildSlots(2 - 1);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::IntersectChain), list_pr.GetChild(0)}, 0);
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeSelectSetOpChainTrampoline(PEGTransformer &transformer,
                                                          GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (dynamic_repeat_opt.HasResult()) {
		auto &dynamic_repeat_pr = dynamic_repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
		dynamic_child_count = dynamic_repeat_children.size();
	}
	auto intersect_chain = process.TakeResult<unique_ptr<SelectStatement>>(0);
	optional<vector<pair<unique_ptr<SetOperationNode>, unique_ptr<SelectStatement>>>> select_set_op_chain_tail {};
	if (dynamic_child_count > 0) {
		vector<pair<unique_ptr<SetOperationNode>, unique_ptr<SelectStatement>>> select_set_op_chain_tail_value;
		select_set_op_chain_tail_value.reserve(dynamic_child_count);
		for (idx_t i = 1; i < 1 + dynamic_child_count; i++) {
			select_set_op_chain_tail_value.push_back(
			    process.TakeResult<pair<unique_ptr<SetOperationNode>, unique_ptr<SelectStatement>>>(i));
		}
		select_set_op_chain_tail = std::move(select_set_op_chain_tail_value);
	}
	auto result = PEGTransformerFactory::TransformSelectSetOpChain(transformer, std::move(intersect_chain),
	                                                               std::move(select_set_op_chain_tail));
	return transformer.MakeResult<unique_ptr<SelectStatement>>(std::move(result));
}

void PEGTransformerFactory::InitializeSelectSetOpChainTailTrampoline(PEGTransformer &transformer,
                                                                     GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(2);
	process.PushChild({transformer.GetRule(PEGRuleId::IntersectChain), list_pr.GetChild(1)}, 1);
	process.PushChild({transformer.GetRule(PEGRuleId::SetopClause), list_pr.GetChild(0)}, 0);
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeSelectSetOpChainTailTrampoline(PEGTransformer &transformer,
                                                              GeneratedTransformProcess &process) {
	auto setop_clause = process.TakeResult<unique_ptr<SetOperationNode>>(0);
	auto intersect_chain = process.TakeResult<unique_ptr<SelectStatement>>(1);
	auto result = PEGTransformerFactory::TransformSelectSetOpChainTail(transformer, std::move(setop_clause),
	                                                                   std::move(intersect_chain));
	return transformer.MakeResult<pair<unique_ptr<SetOperationNode>, unique_ptr<SelectStatement>>>(std::move(result));
}

void PEGTransformerFactory::InitializeIntersectChainTrampoline(PEGTransformer &transformer,
                                                               GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (repeat_opt.HasResult()) {
		auto &repeat_pr = repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto repeat_children = repeat_pr.GetChildren();
		dynamic_child_count = repeat_children.size();
		process.ReserveChildSlots(2 + dynamic_child_count - 1);
		for (idx_t i = repeat_children.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule(PEGRuleId::IntersectChainTail), repeat_children[child_idx].get()},
			                  1 + child_idx);
		}
	} else {
		process.ReserveChildSlots(2 - 1);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::SelectAtom), list_pr.GetChild(0)}, 0);
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeIntersectChainTrampoline(PEGTransformer &transformer,
                                                        GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (dynamic_repeat_opt.HasResult()) {
		auto &dynamic_repeat_pr = dynamic_repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
		dynamic_child_count = dynamic_repeat_children.size();
	}
	auto select_atom = process.TakeResult<unique_ptr<SelectStatement>>(0);
	optional<vector<pair<unique_ptr<SetOperationNode>, unique_ptr<SelectStatement>>>> intersect_chain_tail {};
	if (dynamic_child_count > 0) {
		vector<pair<unique_ptr<SetOperationNode>, unique_ptr<SelectStatement>>> intersect_chain_tail_value;
		intersect_chain_tail_value.reserve(dynamic_child_count);
		for (idx_t i = 1; i < 1 + dynamic_child_count; i++) {
			intersect_chain_tail_value.push_back(
			    process.TakeResult<pair<unique_ptr<SetOperationNode>, unique_ptr<SelectStatement>>>(i));
		}
		intersect_chain_tail = std::move(intersect_chain_tail_value);
	}
	auto result = PEGTransformerFactory::TransformIntersectChain(transformer, std::move(select_atom),
	                                                             std::move(intersect_chain_tail));
	return transformer.MakeResult<unique_ptr<SelectStatement>>(std::move(result));
}

void PEGTransformerFactory::InitializeIntersectChainTailTrampoline(PEGTransformer &transformer,
                                                                   GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(2);
	process.PushChild({transformer.GetRule(PEGRuleId::SelectAtom), list_pr.GetChild(1)}, 1);
	process.PushChild({transformer.GetRule(PEGRuleId::SetIntersectClause), list_pr.GetChild(0)}, 0);
}

