void PEGTransformerFactory::InitializeQualifiedTableFunctionTrampoline(PEGTransformer &transformer,
                                                                       GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (repeat_opt.HasResult()) {
		auto &repeat_pr = repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto repeat_children = repeat_pr.GetChildren();
		dynamic_child_count = repeat_children.size();
		process.ReserveChildSlots(2 + dynamic_child_count - 1);
		for (idx_t i = repeat_children.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule(PEGRuleId::SchemaQualification), repeat_children[child_idx].get()},
			                  1 + child_idx);
		}
	} else {
		process.ReserveChildSlots(2 - 1);
	}
	auto &catalog_qualification_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (catalog_qualification_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::CatalogQualification), catalog_qualification_opt.GetResult()},
		                  0);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeQualifiedTableFunctionTrampoline(PEGTransformer &transformer,
                                                                GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_repeat_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (dynamic_repeat_opt.HasResult()) {
		auto &dynamic_repeat_pr = dynamic_repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
		dynamic_child_count = dynamic_repeat_children.size();
	}
	optional<Identifier> catalog_qualification {};
	if (process.child_results[0]) {
		catalog_qualification = process.TakeResult<Identifier>(0);
	}
	optional<vector<Identifier>> schema_qualification {};
	if (dynamic_child_count > 0) {
		vector<Identifier> schema_qualification_value;
		schema_qualification_value.reserve(dynamic_child_count);
		for (idx_t i = 1; i < 1 + dynamic_child_count; i++) {
			schema_qualification_value.push_back(process.TakeResult<Identifier>(i));
		}
		schema_qualification = std::move(schema_qualification_value);
	}
	auto table_function_name = list_pr.GetChild(2).Cast<IdentifierParseResult>().identifier;
	auto result = PEGTransformerFactory::TransformQualifiedTableFunction(transformer, catalog_qualification,
	                                                                     schema_qualification, table_function_name);
	return transformer.MakeResult<QualifiedName>(std::move(result));
}

void PEGTransformerFactory::InitializeTableFunctionArgumentsTrampoline(PEGTransformer &transformer,
                                                                       GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &list_opt = PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(0)).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (list_opt.HasResult()) {
		auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(list_opt.GetResult());
		dynamic_child_count = list_items.size();
		process.ReserveChildSlots(1 + dynamic_child_count - 1);
		for (idx_t i = list_items.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule(PEGRuleId::FunctionArgument), list_items[child_idx].get()},
			                  0 + child_idx);
		}
	} else {
		process.ReserveChildSlots(1 - 1);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeTableFunctionArgumentsTrampoline(PEGTransformer &transformer,
                                                                GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_list_opt =
	    PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(0)).Cast<OptionalParseResult>();
	if (dynamic_list_opt.HasResult()) {
		dynamic_child_count = CountParseResultsFromList(dynamic_list_opt.GetResult());
	}
	optional<vector<FunctionArgument>> function_argument {};
	auto &function_argument_opt =
	    PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(0)).Cast<OptionalParseResult>();
	if (function_argument_opt.HasResult()) {
		vector<FunctionArgument> function_argument_value;
		function_argument_value.reserve(dynamic_child_count);
		for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
			function_argument_value.push_back(process.TakeResult<FunctionArgument>(i));
		}
		function_argument = std::move(function_argument_value);
	}
	auto result = PEGTransformerFactory::TransformTableFunctionArguments(transformer, std::move(function_argument));
	return transformer.MakeResult<vector<FunctionArgument>>(std::move(result));
}

