void PEGTransformerFactory::InitializeNearestJoinAliasedTrampoline(PEGTransformer &transformer,
                                                                   GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(5);
	process.PushChild({transformer.GetRule(PEGRuleId::Expression), list_pr.GetChild(8)}, 4);
	process.PushChild({transformer.GetRule(PEGRuleId::DistanceOrSimilarity), list_pr.GetChild(7)}, 3);
	auto &approx_or_exact_opt = list_pr.GetChild(3).Cast<OptionalParseResult>();
	if (approx_or_exact_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::ApproxOrExact), approx_or_exact_opt.GetResult()}, 2);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::TableRef), list_pr.GetChild(2)}, 1);
	auto &join_type_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (join_type_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::JoinType), join_type_opt.GetResult()}, 0);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeNearestJoinAliasedTrampoline(PEGTransformer &transformer,
                                                            GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	optional<JoinType> join_type {};
	if (process.child_results[0]) {
		join_type = process.TakeResult<JoinType>(0);
	}
	auto table_ref = process.TakeResult<unique_ptr<TableRef>>(1);
	optional<bool> approx_or_exact {};
	if (process.child_results[2]) {
		approx_or_exact = process.TakeResult<bool>(2);
	}
	optional<unique_ptr<ParsedExpression>> number_literal {};
	auto &number_literal_opt = list_pr.GetChild(5).Cast<OptionalParseResult>();
	if (number_literal_opt.HasResult()) {
		number_literal = PEGTransformerFactory::TransformNumberLiteral(transformer, number_literal_opt.GetResult());
	}
	auto distance_or_similarity = process.TakeResult<OrderType>(3);
	auto expression = process.TakeResult<unique_ptr<ParsedExpression>>(4);
	auto result = PEGTransformerFactory::TransformNearestJoinAliased(transformer, join_type, std::move(table_ref),
	                                                                 approx_or_exact, std::move(number_literal),
	                                                                 distance_or_similarity, std::move(expression));
	return transformer.MakeResult<unique_ptr<TableRef>>(std::move(result));
}

void PEGTransformerFactory::InitializeNearestJoinBareTrampoline(PEGTransformer &transformer,
                                                                GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(5);
	process.PushChild({transformer.GetRule(PEGRuleId::Expression), list_pr.GetChild(8)}, 4);
	process.PushChild({transformer.GetRule(PEGRuleId::DistanceOrSimilarity), list_pr.GetChild(7)}, 3);
	auto &approx_or_exact_opt = list_pr.GetChild(3).Cast<OptionalParseResult>();
	if (approx_or_exact_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::ApproxOrExact), approx_or_exact_opt.GetResult()}, 2);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::NearestBareTableRef), list_pr.GetChild(2)}, 1);
	auto &join_type_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (join_type_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::JoinType), join_type_opt.GetResult()}, 0);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeNearestJoinBareTrampoline(PEGTransformer &transformer,
                                                         GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	optional<JoinType> join_type {};
	if (process.child_results[0]) {
		join_type = process.TakeResult<JoinType>(0);
	}
	auto nearest_bare_table_ref = process.TakeResult<unique_ptr<TableRef>>(1);
	optional<bool> approx_or_exact {};
	if (process.child_results[2]) {
		approx_or_exact = process.TakeResult<bool>(2);
	}
	optional<unique_ptr<ParsedExpression>> number_literal {};
	auto &number_literal_opt = list_pr.GetChild(5).Cast<OptionalParseResult>();
	if (number_literal_opt.HasResult()) {
		number_literal = PEGTransformerFactory::TransformNumberLiteral(transformer, number_literal_opt.GetResult());
	}
	auto distance_or_similarity = process.TakeResult<OrderType>(3);
	auto expression = process.TakeResult<unique_ptr<ParsedExpression>>(4);
	auto result = PEGTransformerFactory::TransformNearestJoinBare(
	    transformer, join_type, std::move(nearest_bare_table_ref), approx_or_exact, std::move(number_literal),
	    distance_or_similarity, std::move(expression));
	return transformer.MakeResult<unique_ptr<TableRef>>(std::move(result));
}

