void PEGTransformerFactory::InitializeUsingClauseTrampoline(PEGTransformer &transformer,
                                                            GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(
	    PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(1)));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::UsingColumnName), list_items[child_idx].get()},
		                  0 + child_idx);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeUsingClauseTrampoline(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_child_count =
	    CountParseResultsFromList(PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(1)));
	vector<Identifier> using_column_name;
	using_column_name.reserve(dynamic_child_count);
	for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
		using_column_name.push_back(process.TakeResult<Identifier>(i));
	}
	auto result = PEGTransformerFactory::TransformUsingClause(transformer, using_column_name);
	return transformer.MakeResult<JoinQualifier>(std::move(result));
}

template <class PROCESS>
void GeneratedSingleChildTransform::InitializeUsingColumnNameTrampoline(PEGTransformer &transformer,
                                                                        ParseResult &parse_result, PROCESS &process) {
	auto &list_pr = parse_result.Cast<ListParseResult>();
	auto &choice_pr = list_pr.Child<ChoiceParseResult>(0);
	auto &choice_result = choice_pr.GetResult();
	process.ReserveChildSlots(1);
	auto child_rule = choice_result.GetRule();
	auto has_transform_process = child_rule && child_rule->transform_process;
	if (choice_result.Name().empty() || choice_result.type == ParseResultType::IDENTIFIER ||
	    choice_result.type == ParseResultType::KEYWORD || choice_result.type == ParseResultType::STRING) {
		return;
	}
	if (!has_transform_process) {
		throw InternalException("No transform process registered for rule '%s'", choice_result.Name());
	}
	process.PushChild({*child_rule, choice_result}, 0);
}

template <class PROCESS>
arena_ptr<TransformResultValue>
GeneratedSingleChildTransform::FinalizeUsingColumnNameTrampoline(PEGTransformer &transformer, ParseResult &parse_result,
                                                                 PROCESS &process) {
	Identifier result;
	if (process.child_results[0]) {
		result = process.template TakeResult<Identifier>(0);
	} else {
		auto &list_pr = parse_result.Cast<ListParseResult>();
		auto &choice_result = list_pr.Child<ChoiceParseResult>(0).GetResult();
		if (choice_result.type == ParseResultType::IDENTIFIER) {
			result = choice_result.Cast<IdentifierParseResult>().identifier;
		} else if (choice_result.type == ParseResultType::KEYWORD) {
			result = Identifier(choice_result.Cast<KeywordParseResult>().keyword);
		} else if (choice_result.type == ParseResultType::STRING) {
			result = Identifier(choice_result.Cast<StringLiteralParseResult>().result);
		} else {
			result = Identifier(PEGTransformerFactory::TransformIdentifierOrKeyword(transformer, choice_result));
		}
	}
	return transformer.MakeResult<Identifier>(std::move(result));
}

