void PEGTransformerFactory::InitializeValuesClauseTrampoline(PEGTransformer &transformer,
                                                             GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(list_pr.GetChild(1));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::ValuesExpressions), list_items[child_idx].get()},
		                  0 + child_idx);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeValuesClauseTrampoline(PEGTransformer &transformer, GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_child_count = CountParseResultsFromList(list_pr.GetChild(1));
	vector<vector<unique_ptr<ParsedExpression>>> values_expressions;
	values_expressions.reserve(dynamic_child_count);
	for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
		values_expressions.push_back(process.TakeResult<vector<unique_ptr<ParsedExpression>>>(i));
	}
	auto result = PEGTransformerFactory::TransformValuesClause(transformer, std::move(values_expressions));
	return transformer.MakeResult<unique_ptr<SelectStatement>>(std::move(result));
}

void PEGTransformerFactory::InitializeValuesExpressionsTrampoline(PEGTransformer &transformer,
                                                                  GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = PEGTransformerFactory::ExtractParseResultsFromList(
	    PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(0)));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::Expression), list_items[child_idx].get()}, 0 + child_idx);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeValuesExpressionsTrampoline(PEGTransformer &transformer,
                                                           GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto dynamic_child_count =
	    CountParseResultsFromList(PEGTransformerFactory::ExtractResultFromParens(list_pr.GetChild(0)));
	vector<unique_ptr<ParsedExpression>> expression;
	expression.reserve(dynamic_child_count);
	for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
		expression.push_back(process.TakeResult<unique_ptr<ParsedExpression>>(i));
	}
	auto result = PEGTransformerFactory::TransformValuesExpressions(transformer, std::move(expression));
	return transformer.MakeResult<vector<unique_ptr<ParsedExpression>>>(std::move(result));
}

