TransformStep GeneratedSingleChildTransform::ExecuteStatement(PEGTransformer &transformer, ParseResult &parse_result,
                                                              arena_ptr<TransformResultValue> child_result) {
	SingleChildTransformState process(parse_result, STATEMENT_OPS, std::move(child_result));
	if (!process.child_results[0]) {
		InitializeStatementTrampoline(transformer, parse_result, process);
		if (process.child) {
			return TransformStep::Child(*process.child);
		}
	}
	auto result = FinalizeStatementTrampoline(transformer, parse_result, process);
	D_ASSERT(!process.child);
	return TransformStep::Complete(std::move(result));
}

